// Target: 0x0038D120 nslPlaySound3D__FUiRA2_Cf
// Reference: NSL/PS2/nsl_ps2_sound.cpp
typedef unsigned int nlUint32;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;
typedef float nlVector3d[3];

struct nslSound
{
  char pad0[0x44];
  nlUint32 used;
  char pad48[0x74 - 0x48];
  nslSoundId myId;
};

struct nslSystem
{
  char pad0[0xc044];
  nslSound soundSlots[256];
  char pad11844[0x15850 - 0x11844];
  int initialized;
  char pad15854[0x15880 - 0x15854];
  int on;
};

extern nslSystem nsl;
extern void nslFatal(const char *format, ...);
extern nslEmitterId nslCreateEmitter(const nlVector3d &position);
extern void nslSetEmitterAutoRelease(nslEmitterId emitterToSet);
extern void nslSetSoundEmitter(nslEmitterId soundEmitter,
                               nslSoundId soundInstance);
extern void nslPlaySound(nslSoundId soundToPlay);

#define NSL_SLOT_MASK 0x000003FF
#define NSL_ID_MASK 0xFFFFFC00
#define NSL_GET_SLOT_FROM_ID(x) ((x) & NSL_SLOT_MASK)

inline void _nslInitialized()
{
  if (nsl.initialized != 1)
    nslFatal("NSL is not initialized");
}

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  unsigned int slot = NSL_GET_SLOT_FROM_ID(checkId);
  unsigned int id = checkId & NSL_ID_MASK;
  if (checkId == 0)
    nslFatal("Invalid sound id %u", checkId);
  if (!nsl.soundSlots[slot].used)
    nslFatal("Invalid sound id %u", checkId);
  if (slot >= 256)
    nslFatal("Invalid sound id %u", checkId);
  if (nsl.soundSlots[slot].myId != checkId)
    nslFatal("Invalid sound id %u", checkId);
  if (id == 0)
    nslFatal("Invalid sound id %u", checkId);
  if (slot >= 257)
    nslFatal("Sound id out of range %u", checkId);
}

#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_SOUND_ID_VALID(checkId) _nslCheckSoundIdValidity(checkId)

void nslPlaySound3D(nslSoundId soundToPlay, const nlVector3d &pos)
{
  if (!nsl.on) return; 
  ASSERT_NSL_INITIALIZED();
  // a convenience function
  ASSERT_SOUND_ID_VALID(soundToPlay);
  nslEmitterId emitId = nslCreateEmitter(pos);
  nslSetEmitterAutoRelease(emitId);
  nslSetSoundEmitter(emitId, soundToPlay);
  nslPlaySound(soundToPlay);
}
